changeSet.sql:
drop materialized view mv_task_fts;
create materialized view mv_task_fts as with task_description_agg as ( select rt.related_object_id as task_id, string_agg(rt.value::text, ', '::text) as description from rich_text rt where rt.passive_id is null and rt.related_object_id is not null group by rt.related_object_id ), task_comments_agg as ( select c.task_id as task_id, string_agg(rt.value::text, ', '::text) as comments from comment c inner join rich_text rt on c.rich_text_id = rt.rich_text_id where rt.passive_id is null and c.passive_id is null group by c.task_id ), task_attachments_agg as ( select m.related_object_id as task_id, string_agg(regexp_replace(m.original_name, '[^\w]+', ' ', 'g')::text, ', '::text) as attachments from media m where m.passive_id is null and m.related_object_id is not null group by m.related_object_id ) select t.task_id, t.workspace_id, t.team_id, t.passive_id, t.owner_id, t.assigned_to, t.title, coalesce(td.description, ''::text) as task_description, tm.task_visibility as team_task_visibility, coalesce(tc.comments, ''::text) as comments_meta, coalesce(ta.attachments, ''::text) as attachments_meta, setweight(to_tsvector('simple', translate(concat_ws(' ', tm.tag, t.team_tag_no), 'ıIİ', 'iii')), 'A') || setweight(to_tsvector('simple', translate(coalesce(t.title, ''::text), 'ıIİ', 'iii')), 'A') || setweight(to_tsvector('simple', translate(coalesce(td.description, ''::text), 'ıIİ', 'iii')), 'B') || setweight(to_tsvector('simple', translate(coalesce(tc.comments, ''::text), 'ıIİ', 'iii')), 'B') || setweight(to_tsvector('simple', translate(coalesce(ta.attachments, ''::text), 'ıIİ', 'iii')), 'B') as fts from task t inner join team tm on tm.team_id = t.team_id left join task_description_agg td on td.task_id = t.task_id left join task_comments_agg tc on tc.task_id = t.task_id left join task_attachments_agg ta on ta.task_id = t.task_id where t.passive_id is null;
create index idx_mv_task_fts_fts_search on mv_task_fts using gin (fts); create unique index idx_mv_task_fts_task_id on mv_task_fts (task_id);
drop materialized view mv_note_fts;
create materialized view mv_note_fts as select n.note_id, n.workspace_id, setweight(to_tsvector('simple', translate(coalesce(n.title, ''::text), 'ıIİ', 'iii')), 'A') || setweight(to_tsvector('simple', translate(coalesce(rt.value, ''::text), 'ıIİ', 'iii')), 'B') as fts from note n left join rich_text rt on rt.rich_text_id = n.rich_text_id and rt.passive_id is null where n.passive_id is null;
create index idx_mv_note_fts_fts_search on mv_note_fts using gin (fts); create unique index idx_mv_note_fts_note_id on mv_note_fts (note_id);
